CREATE OR REPLACE FUNCTION public.guard_new_customer_ticket() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.customer_launch_waitlist WHERE user_id=NEW.user_id) AND NOT public.customer_identity_approved(NEW.user_id) THEN RAISE EXCEPTION 'DTT adult identity approval required before ticket'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.keep_dtt_identity_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.audience IS DISTINCT FROM OLD.audience OR NEW.legal_first_name IS DISTINCT FROM OLD.legal_first_name OR NEW.date_of_birth IS DISTINCT FROM OLD.date_of_birth OR NEW.id_front_path IS DISTINCT FROM OLD.id_front_path OR NEW.id_back_path IS DISTINCT FROM OLD.id_back_path OR NEW.selfie_path IS DISTINCT FROM OLD.selfie_path OR NEW.face_video_path IS DISTINCT FROM OLD.face_video_path OR NEW.document_bucket IS DISTINCT FROM OLD.document_bucket OR NEW.document_expires_on IS DISTINCT FROM OLD.document_expires_on OR NEW.document_number IS DISTINCT FROM OLD.document_number OR NEW.capture_consent_version IS DISTINCT FROM OLD.capture_consent_version OR NEW.capture_consented_at IS DISTINCT FROM OLD.capture_consented_at OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN RAISE EXCEPTION 'Submitted identity evidence is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER keep_dtt_review_evidence BEFORE UPDATE ON public.dtt_identity_reviews FOR EACH ROW EXECUTE FUNCTION public.keep_dtt_identity_evidence();